import { bi as b, type Challenge, type Control, type Lesson, type Source } from '../types';

const range = (id: string, en: string, tr: string, min: number, max: number, value: number, step = 1): Control => ({ id, label: b(en, tr), kind: 'range', min, max, step, default: value });
const toggle = (id: string, en: string, tr: string, value = false): Control => ({ id, label: b(en, tr), kind: 'toggle', default: value });
const text = (id: string, en: string, tr: string, value: string): Control => ({ id, label: b(en, tr), kind: 'text', default: value, maxLength: 24 });
const select = (id: string, en: string, tr: string, values: [string, string, string][], value: string): Control => ({ id, label: b(en, tr), kind: 'select', default: value, options: values.map(([value, en, tr]) => ({ value, label: b(en, tr) })) });
const quiz = (en: string, tr: string, options: [string, string][], correct: number, why: [string, string]): Challenge => ({ question: b(en, tr), options: options.map(([en, tr]) => b(en, tr)), correct, explanation: b(...why) });
const source = (title: string, url: string, year?: number): Source => ({ title, url, year });
